function renderTraining(autoUnlock=false){
 const demoId='TREINO_UND1_000001',weekdays=['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado'];
 const services=['Psicologia','Assistência social'];let requestId=crypto.randomUUID(),enabled={},records=[];
 const dateLabel=d=>d.split('-').reverse().join('/');
 document.title='Ficha do aluno e atendimento — Treinamento';
 document.querySelector('main').innerHTML=`<section class="section registration-intro"><p class="eyebrow">TREINAMENTO · FICHA FICTÍCIA</p><h1>Aluno e atendimento</h1><p class="lead">Consulte a ficha de demonstração e pratique a solicitação de atendimento com a psicóloga ou a assistente social.</p></section><section class="section training-section"><div class="form-status"><strong>Dados exclusivamente fictícios.</strong> Não insira informações de alunos reais. Todos os dias e horários estão abertos para solicitar; o agendamento só é confirmado quando a secretaria envia a confirmação por WhatsApp ao aluno ou responsável.</div><form id="training-login"><div class="form-grid"><label>ID de treinamento<input name="studentId" required maxlength="64" autocomplete="off" spellcheck="false"><small>Use o código de teste fornecido pela coordenação. IDs reais são confidenciais e não devem ser divulgados.</small></label></div><button class="button" type="submit">Consultar aluno</button><p id="training-login-message" role="alert"></p></form><div id="training-workspace" hidden><div class="student-profile"><div class="student-avatar"><img src="/training-avatar.svg" width="160" height="160" alt="Avatar ilustrativo do Aluno Teste; não é foto de uma pessoa real"><small>Foto de registro · ilustração de teste</small></div><div><p class="eyebrow">AMAVALE · APROVADO (FICTÍCIO)</p><h2 tabindex="-1" id="student-profile-title">Aluno Teste</h2><p>Ficha para treinamento da equipe. A identificação do responsável é simulada.</p><dl class="student-details"><div><dt>Nome completo</dt><dd>Aluno Teste</dd></div><div><dt>Pai</dt><dd>Pai de Aluno Teste</dd></div><div><dt>Mãe / responsável</dt><dd>Mãe de Aluno Teste</dd></div><div><dt>Data de nascimento</dt><dd>15/03/2014</dd></div><div><dt>Peso</dt><dd>42,0 kg</dd></div><div><dt>Altura</dt><dd>150 cm</dd></div><div><dt>Kimono</dt><dd>M3 · tamanho ilustrativo</dd></div><div><dt>Rashguard</dt><dd>Juvenil G · tamanho ilustrativo</dd></div><div><dt>Neurodivergência informada</dt><dd>TEA · informação fictícia de demonstração, sem avaliação clínica</dd></div></dl></div></div><div class="student-panels"><section class="privacy-note"><h3>Documentação</h3><ul><li>Documento do aluno: conferido (simulado).</li><li>Documento do responsável: conferido (simulado).</li><li>Autorização dos pais: recebida (simulada).</li><li>Atestado médico: conferido (simulado).</li><li>Foto de registro: avatar ilustrativo.</li></ul><p>Nenhum documento real está disponível neste exercício.</p></section><section class="privacy-note"><h3>Frequência</h3><p>Período demonstrativo: setembro de 2026.</p><dl><dt>Treinos do projeto</dt><dd>10 presenças de 12 treinos · 83,3%</dd><dt>Escola</dt><dd>18 presenças de 20 dias letivos · 90%</dd></dl></section><section class="privacy-note"><h3>Notas escolares</h3><p>3º bimestre de 2026 · escala de 0 a 10 · valores fictícios.</p><table class="school-grades"><caption>Boletim de demonstração</caption><thead><tr><th>Disciplina</th><th>Nota</th></tr></thead><tbody><tr><td>Português</td><td>8,0</td></tr><tr><td>Matemática</td><td>7,5</td></tr><tr><td>Ciências</td><td>8,5</td></tr><tr><td>História</td><td>8,0</td></tr><tr><td>Geografia</td><td>7,0</td></tr></tbody></table></section></div><section class="booking-panel"><h2>Solicitar atendimento</h2><p>Selecione a profissional e indique quando o aluno pode ser atendido. <strong>Todos os dias e horários estão liberados para indicação de preferência.</strong> O agendamento só estará confirmado quando a secretaria enviar a confirmação por WhatsApp ao aluno ou responsável. Até esse contato, a solicitação fica aguardando confirmação da secretaria.</p><form id="training-booking"><div class="form-grid"><label>Atendimento<select name="service" required><option value="">Selecione</option>${services.map(s=>`<option>${s}</option>`).join('')}</select></label><label>Dia da semana<select name="weekday" required><option value="">Selecione</option>${weekdays.map((d,i)=>`<option value="${i}">${d}</option>`).join('')}</select></label><label>Data desejada<input type="date" name="date" required></label><label>Horário desejado<input type="time" name="time" required step="60"><small>Horário de Brasília. Sem grade profissional definida.</small></label></div><p id="weekday-feedback" role="status"></p><div class="privacy-note"><h3>Destinatários da solicitação</h3><p>agenda@projetolutapelacomunidade.com.br, tezzei@gmail.com e a profissional escolhida: psicologa@projetolutapelacomunidade.com.br ou assistente.social@projetolutapelacomunidade.com.br.</p><p>O email contém apenas identificação fictícia e preferência de atendimento. Foto, informação sobre neurodivergência e dados escolares não são anexados.</p><p id="training-email-status" role="status"></p></div><div class="consents"><label><input name="consent" type="checkbox" required><span>Estou ciente de que esta é uma solicitação de treinamento com dados fictícios, aguardando confirmação da secretaria por WhatsApp ao aluno ou responsável. O botão de envio encaminha um email de teste aos destinatários indicados quando o serviço estiver configurado.</span></label></div><div class="service-actions"><button class="button" id="preview-request" type="button">Simular solicitação</button><button class="button" id="send-request" type="submit" disabled>Enviar solicitação por email</button></div></form><div id="training-result" role="status" tabindex="-1" hidden></div><h3>Solicitações deste exercício</h3><div id="training-history"><p>Nenhuma solicitação registrada.</p></div></section><div class="service-actions"><button class="button" id="training-reset" type="button">Reiniciar exercício</button><button class="button" id="training-exit" type="button">Sair da ficha</button></div></div></section>`;
 const login=document.querySelector('#training-login'),workspace=document.querySelector('#training-workspace'),form=document.querySelector('#training-booking'),result=document.querySelector('#training-result'),history=document.querySelector('#training-history'),sendButton=document.querySelector('#send-request');
 const announce=t=>{result.textContent=t;result.className='form-status';result.hidden=false;result.focus()};
 function emailState(){const service=form.elements.service.value;sendButton.disabled=enabled[service]!==true;document.querySelector('#training-email-status').textContent=!service?'Escolha o atendimento para conferir o envio.':enabled[service]?'Envio de email de treinamento disponível para este atendimento.':'O envio por email ainda não está ativo. Os destinatários estão definidos; falta concluir a configuração do serviço de envio. Você pode usar Simular solicitação.'}
 fetch('/api/training-agenda-status',{cache:'no-store'}).then(r=>r.ok?r.json():{}).then(d=>{enabled=d;emailState()}).catch(emailState);
 function validate(){const date=form.elements.date.value,time=form.elements.time.value,day=form.elements.weekday.value;form.elements.date.setCustomValidity('');form.elements.time.setCustomValidity('');if(date&&day!==''&&new Date(date+'T12:00:00Z').getUTCDay()!==Number(day))form.elements.date.setCustomValidity('Escolha uma data que corresponda ao dia da semana selecionado.');if(date&&time&&new Date(date+'T'+time+':00-03:00')<=new Date())form.elements.time.setCustomValidity('Escolha uma data e um horário futuros.');document.querySelector('#weekday-feedback').textContent=date?'A data escolhida cai em '+weekdays[new Date(date+'T12:00:00Z').getUTCDay()]+'.':'';return form.reportValidity()}
 function data(){return {studentId:demoId,service:form.elements.service.value,weekday:Number(form.elements.weekday.value),date:form.elements.date.value,time:form.elements.time.value,consent:form.elements.consent.checked,requestId}}
 function render(){history.replaceChildren();if(!records.length){history.textContent='Nenhuma solicitação registrada.';return}for(const r of records){const p=document.createElement('p');p.className='privacy-note';p.textContent=`${r.service} · ${weekdays[r.weekday]}, ${dateLabel(r.date)} às ${r.time} · ${r.state}`;history.append(p)}}
 login.addEventListener('submit',e=>{e.preventDefault();const ok=login.elements.studentId.value.trim().toUpperCase()===demoId;login.reset();document.querySelector('#training-login-message').textContent=ok?'':'ID de treinamento não reconhecido. Solicite o código à coordenação.';if(!ok)return;login.hidden=true;workspace.hidden=false;document.querySelector('#student-profile-title').focus()});
 form.addEventListener('input',()=>{requestId=crypto.randomUUID();form.elements.date.setCustomValidity('');form.elements.time.setCustomValidity('')});form.elements.service.addEventListener('change',emailState);
 document.querySelector('#preview-request').addEventListener('click',()=>{if(!validate())return;const d=data();records.push({...d,state:'Simulação · aguardando confirmação da secretaria por WhatsApp · email não enviado'});render();announce('Solicitação simulada: aguardando confirmação da secretaria por WhatsApp ao aluno ou responsável. Nenhum email foi enviado e nenhum horário foi reservado.')});
 form.addEventListener('submit',async e=>{e.preventDefault();if(!validate())return;if(!enabled[form.elements.service.value]){emailState();return}sendButton.disabled=true;try{const d=data(),r=await fetch('/api/training-agenda',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}),response=await r.json();announce(response.message||'Não foi possível confirmar o envio.');if(r.ok){records.push({...d,state:'Email de treinamento enviado · aguardando confirmação da secretaria por WhatsApp · sem reserva real'});render();form.reset();requestId=crypto.randomUUID()}}catch{announce('Não foi possível confirmar o envio. Os campos foram preservados.')}finally{emailState()}});
 document.querySelector('#training-reset').addEventListener('click',()=>{records=[];render();form.reset();requestId=crypto.randomUUID();emailState();result.hidden=true;document.querySelector('#weekday-feedback').textContent=''});
 document.querySelector('#training-exit').addEventListener('click',()=>{if(location.pathname.replace(/\/+$/,'')==='/agendamento'){location.reload();return}workspace.hidden=true;login.hidden=false;login.reset();login.elements.studentId.focus()});emailState();if(autoUnlock){login.hidden=true;workspace.hidden=false;document.querySelector('#student-profile-title').focus()}
}




if(location.pathname.replace(/\/+$/,'')==='/treinamento')renderTraining();
window.addEventListener('lpc:training-access',()=>renderTraining(true));

